def _nilai(kind: str, detik: int) -> dict:
    """Nilai token untuk satu kombinasi."""
    return {
        "detik": detik,
        "produk": "product " if kind == "product-only" else "",
        **ANGGARAN[detik],
    }


def render_prompt(kind: str, detik: int) -> str:
    """Susun prompt utuh untuk `kind` (product-only|product+model) + durasi."""
    if kind not in _KEPALA:
        raise ValueError(f"kind tidak dikenal: {kind!r}")
    if detik not in SPEC:
        raise ValueError(f"durasi tidak didukung: {detik} (pilih {sorted(SPEC)})")
    v = _nilai(kind, detik)
    return (
        _KEPALA[kind]
        + SPEC[detik].format(**v)
        + _EKOR[kind].format(**v)
    )
